import type { NewToolSlug } from "./new-tools";

type SupportingContent = { instructions: string[]; uses: string[]; limitations: string; faqs: Array<[string,string]>; guide?: Array<{ heading: string; paragraphs: string[] }> };
export const stage5Content: Partial<Record<NewToolSlug, SupportingContent>> = {
  "signature-generator": { instructions:["Type your name or draw directly on the canvas.","Choose a cursive style, ink color, and stroke thickness, then keep the transparent background on for clean overlays.","Preview the result and download the signature as a high-resolution image."], uses:["Email and document signatures","Signatures for forms and letterheads","Personal branding and social profiles"], limitations:"A typed signature is a styled rendering of your name, not a certified electronic signature; check the requirements wherever a legally binding signature is needed.", faqs:[["Is this signature generator free?","Yes. The signature generator is free to use in the browser and requires no account."],["Can I export with a transparent background?","Yes. Keep the transparent background option on and the download has no white box behind the signature."],["Can I draw my own signature instead of typing?","Yes. Switch to draw mode and sign with a mouse, pen, or touch."],["Which signature styles can I choose?","Four named styles: Classic Cursive, Segoe Script, Brush Script MT, and Kalam. Pick one from the Signature style menu and preview it in your own name."],["Is a typed signature legally binding?","No. A typed signature here is a styled image of your name, not a certified electronic signature. Check the requirements wherever a legally binding signature is needed."],["Can I download an SVG of my signature?","No. Downloads are PNG, JPG, and PDF; SVG export is not offered."],["Does the pen thickness control work in typed mode?","No. The thickness slider applies in draw mode only; typed signatures render at a fixed size."],["Can I use this signature on a legal document?","For everyday documents, usually yes. For contracts or anything a bank or court will rely on, check the recipient's requirements first — this tool makes a picture of a name, not a certified electronic signature with an audit trail."],["How do I add my signature to a Word document?","Download the PNG with a transparent background, then use Insert > Pictures in Word, set Wrap Text to In Front of Text, and drag it above the signature line."],["Can I upload a photo of my paper signature?","No. This generator types or draws a signature on screen; it cannot digitise a photo of a signature already on paper."]], guide: [{"heading": "How to add your signature to Word, PDF, Google Docs, and email", "paragraphs": ["Download the signature as a PNG with the transparent background switched on. A transparent PNG sits cleanly on any document background, while a JPG always carries a white box behind the ink — so use PNG whenever the signature goes on top of other content.", "In Microsoft Word, place the cursor where the signature belongs, then use Insert > Pictures and choose the downloaded PNG. Right-click the image, choose Wrap Text > In Front of Text, and drag it into place above the typed name. In Google Docs, use Insert > Image > Upload from computer, then drag a corner handle to size it — a width of roughly 4–5 cm (about 1.5–2 inches) looks natural on a letter. For a PDF, open the file in a PDF editor that supports images and use its Add image or Insert image command, then position the signature above the signature line. In an email, insert the PNG into the message body rather than attaching it, so the recipient sees the signature in place; most mail apps, including Gmail and Outlook, offer an Insert photo or Insert picture button in the compose window.", "Whatever the destination, test the result at the size it will actually be read. A signature that looks good at full screen can look thin or faint when shrunk to a signature line, so check the document at 100% zoom — or print one page — before sending it."]}, {"heading": "Making a typed or drawn signature look real", "paragraphs": ["Drawn signatures usually look more personal than typed ones, because the stroke varies the way a real pen does. If you use draw mode, sign in one smooth motion at a natural size — small, careful mouse movements produce wobbly lines. A pen thickness around the middle of the 1–12 range suits most names; go thicker for short names and thinner for long ones so the signature fits the 1200 × 420 canvas without crowding.", "Typed signatures are a good fallback when drawing with a mouse feels awkward. Preview all four styles in your own name before choosing: Classic Cursive is the most formal, Segoe Script and Brush Script MT are looser, and Kalam has a handwritten, slightly uneven feel. Keep the ink black or dark blue — bright colours read as decoration, not a signature — and leave the transparent background on.", "Keep the signature short. A first name plus surname, or initials plus surname, reads better than a full middle name at small sizes. If the name is long, try the signature at a smaller preview size first: if you cannot read it at signature-line size, neither can anyone else."]}, {"heading": "Is a typed or drawn signature legally valid?", "paragraphs": ["A signature made with this tool is a picture of a name, not a certified electronic signature. It carries no proof of who made it, no timestamp, and no tamper-evident seal — so whether it counts as a signature depends on the document, the place, and the other side's requirements. This is general information, not legal advice.", "In the United States, the ESIGN Act (2000) and the state-level UETA recognise electronic signatures where the signer intends to sign and the process records that intent — but an image file on its own records neither. In the European Union, the eIDAS regulation recognises simple, advanced, and qualified electronic signatures, with qualified signatures carrying the strongest legal weight; a plain image is, at most, a simple electronic signature. Some documents need more: wills, certain property transfers, and court filings in some places require specific forms, witnesses, or notarisation, and a pasted image will not satisfy them.", "For everyday uses — signing a letter, adding a name to a form that accepts an image, or branding a document — a typed or drawn signature is normally fine. For anything binding, such as a contract, a tax form, or a document a bank or court will rely on, check what that recipient requires first, and use a proper e-signing service with an audit trail when they ask for one. When in doubt, ask the recipient before sending."]}, {"heading": "Keeping your signature consistent", "paragraphs": ["A signature works best when it is the same everywhere. Once you have a version you like, download the PNG and keep the file — reuse that same image in every document instead of drawing a fresh signature each time. A signature that changes shape from document to document looks less convincing than one that is identical every time, even if the identical one is typed rather than drawn.", "Save the file under a clear name, such as signature-transparent.png, and keep a copy in the same folder as your CV or letter templates so you can find it. If you change your name or your signature style, replace the file everywhere at once rather than letting old and new versions circulate side by side.", "Check the size each time you place it. A signature pasted at 10 cm wide on a letter looks like a stamp, not a signature; at 4–5 cm wide it reads naturally. Resize by dragging a corner handle so the proportions stay fixed, and never stretch it wider than it is tall — a squashed signature is the fastest way to make a real one look fake."]}] },
  "word-search-maker": { instructions:["Enter your word list, one word per line or separated by commas — lists of 3–40 words work best.","Choose a grid size and a difficulty preset, then fine-tune the four direction switches: horizontal, vertical, diagonal, and backwards work independently.","Turn on the highlighted answer key when you need one, then print — the key prints on a second page so you can hand out the puzzle alone — or download the puzzle and the key as separate PNG images.","Press “Generate new puzzle” for a fresh placement of the same word list."], uses:["Vocabulary practice for any subject","Classroom warm-ups and homework sheets","Family and party word puzzles"], limitations:"Very long words may not fit a small grid; the maker reports words it could not place so you can enlarge the grid or shorten them. Words are upper-cased and accented letters are folded to their base letter.", faqs:[["Is this word search maker free?","Yes. You can make and download word search puzzles in the browser without an account."],["How many words can I add?","Lists of 3–40 words work best. The size guide table below the tool shows which grid fits which list: a 10 × 10 grid suits 3–8 short words, while the 25 × 25 grid fits 20–40 words. If a word cannot be placed, increase the grid size or use a shorter word."],["Does it include an answer key?","Yes. Enable the highlighted answer key to show every placed word in the puzzle. When you print, the key appears on a separate second page, and you can also download the key as its own PNG."],["Can I download the puzzle as a PNG?","Yes. “Download puzzle PNG” saves the puzzle as an image, and “Download answer key PNG” saves the key as a separate image."],["Which grid sizes are available?","10 × 10, 12 × 12, 15 × 15, 18 × 18, 20 × 20, 22 × 22, and 25 × 25. Larger grids fit longer word lists."],["What happens to words with accents or hyphens?","Accented letters are folded to their base letter, so café becomes CAFE and piñata becomes PINATA. Hyphens and other non-letters are removed, so well-known becomes WELLKNOWN."],["What do easy, medium, and hard change?","The directions words can run in. Easy uses across and down only; medium adds diagonals; hard adds backwards too — 2, 4, and 8 directions. The four direction switches below the preset let you make your own combination, for example diagonals on and backwards off."],["How are words placed?","Longest words first, with a preference for slots that cross words already placed, so the puzzle has more intersections. Empty cells are filled with letters drawn from your word list's own letter distribution, so the answers stand out less."]] },
  "invitation-maker": { instructions:["Pick a template for the occasion: birthday, wedding, party, graduation, baby shower, or anniversary.","Fill in the event, host, date, time, venue, and message, then adjust the font and colors.","Review the live preview and download the invitation as PNG, JPG, or PDF, or print it."], uses:["Birthday and graduation invitations","Wedding and anniversary invitations","Party and baby shower invitations"], limitations:"This invitation maker creates print-ready invitation designs; it does not send invitations or track RSVPs.", faqs:[["Is this invitation maker free?","Yes. You can design and download invitations in the browser without an account."],["What can I change on an invitation?","You can change the template, wording, font, text color, and background color before downloading."],["Can I print the invitation?","Yes. Download it as PNG, JPG, or PDF, or print the preview directly from the browser."],["How many invitation templates are there?","Seven themes: birthday, wedding, party, graduation, baby shower, anniversary, and a custom theme."],["What fonts can I use?","Three: Georgia, Kalam (handwriting), and Arial."],["What size is the downloaded invitation?","A square 1000 × 1000 px image, exported as PNG, JPG, or PDF."],["Can I add a photo or animation?","No. The maker uses a flat background color with a double border; it does not add photos, illustrations, or animated exports."],["What size is the invitation when printed?","The download is a square 1000 × 1000 px image, about 3.3 inches across at 300 DPI. Download the PDF for printing and use photo paper at the native square size."],["Can I write my own wording for a wedding invitation?","Yes. Every field — event, host, date, time, venue, message, and the RSVP line — is editable, so you can write formal wedding wording or casual party wording in the same maker."]], guide: [{"heading": "Invitation wording for each occasion", "paragraphs": ["Every theme in this maker uses the same seven fields — event, host, date, time, venue, message, and an RSVP line — so the wording, not the layout, is what makes each occasion feel right. Start with the event line: put the person's name and the occasion first ('Maya's 30th Birthday', 'The Wedding of Ana and Ben', 'Rahim's Graduation'), because that is the line guests read first.", "Birthday invitations work best with a warm, short message and the practical details up front: what is happening, when, and where. A line such as 'Join us for cake, music, and an afternoon with friends' says more than a long paragraph, and the RSVP line should carry a phone number or a name guests can reply to. For a child's birthday, add the age and the name of the host parent in the host field.", "Wedding invitations should name both people and keep the tone formal: 'The Wedding of Ana and Ben' as the event, the couple's families or the couple themselves as host, and the ceremony time and venue spelled out in full. Anniversary invitations follow the same shape, with the number of years in the event line ('25th Wedding Anniversary'). Graduation invitations name the graduate and the school, and usually add the ceremony time followed by a reception note in the message field. Baby shower invitations name the parent-to-be and the host, and the message field is the place for a gift note if there is one.", "Party invitations can be casual — the theme colour and a one-line message carry the tone — but still give the date, time, and venue in full. The Custom theme prints 'You are invited' as its heading, so it suits anything that does not fit the other six: a housewarming, a farewell, or a community gathering. Whatever the occasion, read the finished card once as a guest would: if any of who, what, when, or where is missing, add it before downloading."]}, {"heading": "How to design and export your invitation", "paragraphs": ["Pick the theme for the occasion first — birthday, wedding, party, graduation, baby shower, anniversary, or custom — then fill in the fields from the top down. Choose the font to match the tone: Georgia reads formal and suits weddings and anniversaries, Kalam adds a handwritten feel for birthdays and baby showers, and Arial stays clean and neutral for anything else. The theme sets the background colour and the double-border accent; you can also pick your own background and text colours.", "Check the live preview before downloading. Long event titles wrap onto two lines, which is fine, but a message longer than two or three sentences will crowd the square card — shorten it and move extra details (parking, dress code, gift notes) into a message to guests instead. When the card looks right, download it as a PNG for sharing in messages and on social media, or as a PDF for printing.", "The download is a square 1000 × 1000 px image. That is crisp on phone screens and in messaging apps, and it prints at about 3.3 inches across at 300 DPI. For a larger printed card, download the PDF and print it on photo paper at its native square size, or ask a print shop to enlarge it — enlarging a 1000 px image much beyond 5 inches across will soften the edges."]}, {"heading": "What this invitation maker does not do", "paragraphs": ["This maker designs a single printable card. It does not add photos or illustrations — the design is a flat background colour with a double border — and it does not export animated cards or video. There is no guest list, no RSVP tracking, and no sending: you download the finished image and share it yourself, by message, email, or print.", "If you need RSVPs, add your phone number or an email address to the RSVP line and collect replies yourself, or use a dedicated invitation service for the guest management and keep this maker for the card itself. For a printed invitation, print one test copy first and check the colours — flat background colours can look darker on paper than on screen."]}, {"heading": "Wording examples you can copy", "paragraphs": ["Birthday: event 'Maya's 30th Birthday', host 'The Morgan Family', message 'Join us for cake, music, and an afternoon with friends. The party starts at four — bring your dancing shoes.' RSVP: 'RSVP: Maya, 555-0123'.", "Wedding: event 'The Wedding of Ana and Ben', host 'Mr and Mrs Carter, together with Mr and Mrs Ali', message 'We would be delighted if you could join us as we celebrate our marriage, followed by dinner and dancing.' RSVP: 'Kindly reply by 1 May: Ana, 555-0145'.", "Graduation: event 'Rahim's Graduation', host 'The Ahmed Family', message 'Join us to celebrate Rahim's graduation from City High School. Ceremony at 10 AM, lunch to follow at our home.' Baby shower: event 'A Baby Shower for Sara', host 'Hosted by Lina', message 'Join us for an afternoon of games, gifts, and cake as we welcome Sara's little one.' Replace the names, dates, and details with your own — the shape of each example works for any version of the occasion."]}] },
  "cursive-text-generator": { instructions:["Type the text you want in cursive.","Choose a cursive style and adjust the size to fit your design.","Export the result as PNG, JPG, or PDF."], uses:["Names and quotes in cursive lettering","Worksheet headings and classroom displays","Cards, posters, and social graphics"], limitations:"The output is cursive text rendered in a chosen style, not your own personal handwriting.", faqs:[["Is this cursive text generator free?","Yes. You can create and export cursive text in the browser without an account."],["What formats can I download?","PNG, JPG, and PDF are available from the export controls."],["Can I use the result on a printed worksheet?","Yes. Export at a size that fits your page and preview before printing."],["Which cursive fonts are available?","Four named fonts: Classic Cursive, Segoe Script, Brush Script MT, and Kalam."],["Can I copy cursive text to paste in Instagram or WhatsApp?","Yes. Switch to the Copy-paste text mode above the tool: pick one of the ten Unicode script styles, tap Copy, and paste it into a bio, caption, or chat. The image mode still exports a picture — use that for worksheets, cards, and print."],["Can I download an SVG or transparent PNG?","No. Downloads are PNG, JPG, and PDF on a solid background; SVG and transparent PNG are not offered."],["How much text can I convert at once?","Up to 2,000 characters in image mode, and up to 500 characters in copy-paste text mode."],["Why do some characters show as boxes after pasting?","The app or device you pasted into lacks a font for those Unicode characters. Try the plain Script style, which has the widest support, and test on the device your audience uses."],["Can I use Unicode cursive in my Instagram bio?","Yes. Copy a style from the Copy-paste text mode and paste it into your bio. Keep the important words (like your name) in plain text too, so search and screen readers still find them."],["Which is better — the image or the copy-paste text?","Images keep the exact font and colour and suit print, cards, and worksheets. Copy-paste text stays editable and searchable and suits bios, captions, and chats."]], guide: [{"heading": "Unicode cursive vs image cursive: which one do you need?", "paragraphs": ["This page now offers two different kinds of cursive, and they solve different problems. Copy-paste text converts your words into Unicode script characters — real text that keeps its cursive look when you paste it into a bio, caption, chat message, or username. Image export renders your words in a cursive font and downloads them as a PNG, JPG, or PDF picture.", "Use copy-paste text when the words themselves have to travel: an Instagram or TikTok bio, a WhatsApp status, a Discord name, or a caption. The styled characters are the text, so they copy, paste, and search like ordinary letters. Use image export when the look has to be exact: a worksheet heading, a card, a poster, or anything printed. An image keeps the exact font, size, and colour you chose, while pasted Unicode text is displayed in whatever font the receiving app chooses.", "The trade-off is control. An image always looks the same everywhere, but it cannot be edited as text, searched, or read by a screen reader. Unicode text stays editable and searchable, but its appearance depends on the app and device showing it — and a few characters may fall back to a different style if the app's font lacks them."]}, {"heading": "How the copy-paste styles work", "paragraphs": ["The copy-paste styles are built from the Mathematical Alphanumeric Symbols block in Unicode: ordinary letters are replaced with their script equivalents, so 'A' becomes a script capital and 'a' becomes a script small letter. Ten styles are offered: Script and Bold Script, plus Script with an underline, double underline, overline, strikethrough, tilde, tilde below, a joining tie between letters, and dots below.", "Type or paste up to 500 characters, pick a style, and tap Copy next to it. Numbers and punctuation pass through unchanged — Unicode has no script digits — so 'Class of 2026' keeps its numerals in plain form. The text is converted entirely in your browser; nothing is uploaded.", "Decorated styles use combining marks — small characters that attach to the letter before them. An underline style adds a low line after each letter, a strikethrough adds a long stroke through each letter, and the tied style joins neighbouring letters with a double inverted breve. Because the marks are separate characters, very long decorated text can behave oddly in some apps; keep bios and captions short."]}, {"heading": "Where Unicode cursive works — and where it does not", "paragraphs": ["Unicode script characters work in most modern apps that accept pasted text: Instagram and TikTok bios and captions, WhatsApp and Telegram messages, Discord names and messages, Facebook posts, and X posts. If a style shows correctly in the preview here, it will usually show correctly there — but not always, because each app renders text with its own fonts.", "If you see empty boxes or question marks instead of letters, the app or device you pasted into does not have a font covering those characters. Older phones, some desktop apps, and a few games are the usual cases. Try the plain Script style first — it has the widest support — and test the result on the device your audience will use before posting it somewhere permanent.", "Screen readers may read styled text letter by letter rather than as words, and search engines treat styled characters as different characters from plain ones — so a bio written entirely in script text will not match a plain-text search for your name. For anything that must be found or read aloud, keep the important words in plain text and use cursive for decoration only. For a closer look at the same idea across more styles, the Fancy Text Generator on this site converts text into eleven Unicode styles, including bold, italic, and fraktur."]}, {"heading": "Getting a good image export", "paragraphs": ["For the image mode, choose one of the four named fonts — Classic Cursive, Segoe Script, Brush Script MT, or Kalam — and set a size between 32 and 180. Short text (a name or a quote) looks best large and centred; longer text needs a smaller size and left alignment, or it will overflow the canvas. Use the letter-spacing slider to open up cramped letterforms and the line-height slider when the text runs to two or more lines.", "Download as PNG for the sharpest result, JPG for a smaller file, or PDF when the text goes into a document. The download uses the same high-resolution canvas as the preview, so what you see is what you get — check the preview at full width before exporting."]}, {"heading": "Cursive, calligraphy, and script lettering — what's the difference?", "paragraphs": ["The three words are often used as if they meant the same thing, and they do not. Cursive is a way of writing in which the letters of a word are joined — the style taught in schools for handwriting. Calligraphy is the art of decorative lettering with a broad-nib or brush pen, where the thick and thin of each stroke is deliberate. Script lettering is a looser term for any flowing, handwritten-looking typeface, including the fonts this page renders.", "This page's image mode renders script lettering: typed text set in a cursive-style font. It is not calligraphy — no pen angle or pressure is simulated — and it is not your own cursive handwriting. The copy-paste mode is different again: it replaces letters with Unicode script characters, which is a text encoding trick, not a font at all. Knowing which one you are using matters when you describe the result to someone else — a worksheet heading is script lettering, a wedding invitation in flowing capitals is calligraphy-style, and a bio in script characters is Unicode text.", "For real calligraphy practice, the Calligraphy Generator on this site renders text in the two most calligraphic styles in the handwriting engine (Soft Cursive and Ink Flow), and the Handwriting Worksheet Generator makes tracing sheets in cursive mode. Neither is a pen simulator — both render typed text — but they are the closest this site comes to calligraphy, and they pair well with this page's headings."]}, {"heading": "Choosing a style for a bio, a caption, or a username", "paragraphs": ["For a bio or a username, plain Script is the safest choice: it has the widest support across apps and devices, and it stays readable at small sizes. Bold Script suits a single display name or a short heading, but a whole bio in bold script is tiring to read. Save the decorated styles — underline, overline, strikethrough, tilde — for one or two words you want to emphasise, not for the whole text.", "For a caption, match the style to the mood: Script for something personal, Tied Script for a playful line where the joined letters echo handwriting, Struck-Through Script for a joke or a correction ('old me' crossed out, 'new me' in plain Script). Keep captions short — decorated Unicode text gets harder to read with every added character, and a caption that needs effort to decode will be skipped.", "For a username, test it before committing: paste the styled name into the app, log out, and look at it as a stranger would. If any letter shows as a box, switch to plain Script or keep the name in plain text and put the cursive in the bio instead. A username has to work everywhere the bio does not — in search results, mentions, and notifications — so plain text is often the better home for the name itself."]}] },
  "assignment-maker": { instructions:["Fill in the title, subject, grade, and student and teacher details.","Write the instructions and the assignment content, using the formatting buttons for headings, lists, and page breaks.","Choose A4 or Letter, review the live preview, then download or print the assignment."], uses:["Homework and class assignment sheets","Revision packs with a clear title and instructions","Teacher handouts with a tidy header and date"], limitations:"Formatting stays text-based with headings, lists, and page breaks; the assignment maker does not add images to the page.", faqs:[["Is this assignment maker free?","Yes. You can build and print assignments in the browser without an account."],["Which paper sizes are supported?","A4 and US Letter are supported, with a live preview for each."],["Can I add page breaks?","Yes. Use the page-break button to split long assignments across pages."],["Which details can I add to an assignment?","Title, subject, grade, topic, student, teacher, institution, and date — all shown in the header."],["Does it write the assignment for me?","No. You write the instructions and content; the maker formats them into a tidy printable sheet."],["Can I export to Word?","No. Export is Print / Save as PDF from the preview; Word (.doc) export is not offered."],["Can I add an answer key or rubric?","No. The maker formats your assignment text; it has no answer-key or rubric block."],["How do I add marks or point values?","Type them into the assignment content — for example 'Question 1 (10 marks)' or a 'Marks' list at the end. The maker has no separate rubric or answer-key block."],["Is there a template I can start from?","Yes. The maker loads with a worked water-cycle example already filled in. Edit its title, subject, and content to make your own assignment instead of starting from a blank page."],["Can I make a question-only worksheet?","Yes. Leave the instructions short and list numbered questions in the content. The header fields (title, subject, grade, date) still appear on the finished sheet."]], guide: [{"heading": "How to write assignment instructions that students actually follow", "paragraphs": ["Write the instructions as if the student will read them once, quickly, before starting. One task per sentence, plain verbs — 'Explain', 'List', 'Compare', 'Draw' — and no jargon the class has not met. Put the essential facts first: what to do, how long or how much to write, and when it is due. The date field in the header carries the due date; the instructions box carries everything else.", "State what will be marked. If spelling counts, say so. If diagrams are required, say so. If the work must be handwritten or word-processed, say so here rather than assuming it. A short instruction that names the deliverable ('Write three paragraphs, about 150 words, with one labelled diagram') produces better work than a long instruction that never says what 'done' looks like.", "Keep the header complete: title, subject, grade, topic, student, teacher, institution, and date all appear on the finished sheet. A sheet with a blank header looks unfinished and is easy to lose in a pile; a filled header tells the student, the teacher, and the parent exactly what the work is."]}, {"heading": "Adding point values and marks", "paragraphs": ["This maker has no rubric or answer-key block, so write marks as ordinary lines in the assignment content — for example a short 'Marks' list at the end, or a number in brackets after each question. Weight the marks by the effort each question takes, and make the total a round number, usually 100, so a score is easy to read as a percentage.", "A workable split for a five-question assignment is 10 marks for a short recall question, 20 each for three medium questions, and 30 for the longest answer — 10 + 20 + 20 + 20 + 30 = 100. Put the marks where the student sees them before answering, not hidden at the end, and keep the hardest question last so a student who runs out of time loses the fewest marks on the easy ones.", "If you mark with a rubric, write the rubric as a short list in the content too — for example 'Content 60, Presentation 20, Spelling 20' — so the student knows how the total is built. The formatting buttons give you headings, subheadings, bullets, and numbered lists; use a numbered list for the questions and a bullet list for the marking notes, and the sheet stays easy to scan."]}, {"heading": "Worked example: a Grade 6 science assignment", "paragraphs": ["Title: 'Our Solar System'. Subject: Science. Grade: Grade 6. Topic: 'The eight planets and their order from the Sun'. Instructions: 'Answer all five questions in full sentences. Use your class notes and the textbook. Write neatly and label any diagram you draw. Due Friday.'", "Question 1 (10 marks): 'Name the eight planets in order from the Sun.' Question 2 (20 marks): 'Explain why Mercury is hot during the day and cold at night.' Question 3 (20 marks): 'Compare Earth and Mars: give two similarities and two differences.' Question 4 (20 marks): 'Draw a labelled diagram of the solar system showing the Sun and the eight planets in order.' Question 5 (30 marks): 'A new planet is discovered between Mars and Jupiter. Describe three things scientists would need to find out about it, and explain why each one matters.'", "Notice what the example does: the first question is quick recall, the middle questions ask for explanation and comparison, and the last question asks the student to think, which is why it carries the most marks. The instructions state the rules once — full sentences, due date, neatness — and the questions carry the marks in brackets so the weighting is visible before the student starts. Build your own assignment the same way: a short recall opener, two or three middle questions, and one thinking question worth the most."]}, {"heading": "Formatting and printing tips", "paragraphs": ["Use the formatting buttons instead of typing markdown by hand: Heading for the main sections, Subheading for parts, Bullets for lists of items, and Numbered list for the questions themselves. Insert a page break before a new section when the assignment runs long — the preview shows a dashed line where the break falls, and the printed sheet splits there.", "Choose A4 or Letter to match your printer paper before you print; a sheet made for A4 and printed on Letter will lose its bottom lines. Review the live preview end to end, check that no question is split awkwardly across a page break, and print one copy before printing a class set."]}, {"heading": "Assignment types: worksheet, essay, problem set, project", "paragraphs": ["The maker is one blank layout, so the assignment type is decided by how you fill it, not by a template picker. A worksheet is a numbered list of short questions with marks in brackets — the water-cycle example the tool loads with is a worksheet. An essay prompt is a title, a short instruction, and one or two open questions with a word count ('Write about 300 words'), plus a marks split such as 'Content 60, Structure 20, Language 20'.", "A problem set is a list of problems, each on its own line, with the marks showing the difficulty — easy problems first, worth fewer marks, and the hardest last. Use the page-break button between sections when a problem set runs long, so no problem is split across a page. A project is a title page plus sections: use a Heading for each part ('Aim', 'Method', 'Results', 'Conclusion') and a Subheading inside each part, with the instructions box carrying the deadline and the submission rules.", "A reading response is the shortest form: the title of the text, the instruction ('Write a short response to the chapter'), and three prompts — what happened, what it means, and what you think of it. Whatever the type, keep the same skeleton: header filled in, instructions stating the deliverable and the due date, numbered questions or headed sections, and marks where the student can see them."]}] },
  "sentence-scramble-generator": { instructions:["Enter your sentences, one per line — up to 30 sentences per worksheet.","Choose easy, medium, or hard difficulty and how many versions (up to 5) you need.","Turn on the answer key, then regenerate or copy the scrambled sentences."], uses:["Sentence scramble generator worksheets for reading and writing practice","Word-order practice for language learners","Homework and classroom worksheets with answer keys"], limitations:"The tool shuffles the words in each sentence; it does not check grammar or meaning, so review each scrambled sentence before handing it out.", faqs:[["Is this sentence scramble generator free?","Yes. You can make and copy sentence scramble worksheets in the browser without an account."],["How many sentences and versions can I make?","Up to 30 sentences, one per line, and up to 5 versions of the same worksheet."],["Does it include an answer key?","Yes. Turn on the answer key to show the original sentences in the correct order."]] },
  "number-grid-generator": { instructions:["Set the first and last value, then choose the row and column count.","Choose a positive or negative sequence step and add blank cells for student practice.","Check the live grid before downloading PNG, SVG, or a print-ready PDF."], uses:["Printable number chart wall displays for early numeracy","Missing-number assessments","Custom calendar-style sequences"], limitations:"Very large grids become hard to read on one sheet; the preview caps rendered output at 500 cells.", faqs:[["Can the grid count backward?","Yes. Use a negative sequence step and set the end below the start."],["Are blank cells random?","They are deterministic within the current preview and can be reshuffled."],["Will cell sizes be preserved?","SVG preserves vector dimensions; PDF and PNG render the same visible layout."]] },
  "printable-number-charts": { instructions:["Choose a 0–99, 1–100, 1–120, multiplication, empty, or missing-numbers chart.","Enter comma-separated numbers to highlight, shade multiples for skip counting, and add a custom heading with name and date lines when the sheet is for a class.","For a missing-numbers chart, set the percentage of blank cells and shuffle for a fresh worksheet — the answer key below shows the complete chart.","Select A4, US Letter, A3, or US Legal, switch orientation if needed, then export or print the preview."], uses:["Early numeracy wall charts","Multiplication reference sheets","Missing-numbers practice with a separate answer key","Reusable empty-chart exercises"], limitations:"Highlights match exact numeric cell values; ranges such as 10–20 should be entered as individual values. Missing-numbers blanks are chosen by a seeded random draw, so the same percentage and shuffle give the same worksheet.", faqs:[["Can I make a blank chart?","Yes. Empty 100 chart keeps the full grid while removing the numbers — or open the dedicated blank chart page for a sheet with its own heading and name and date lines."],["What does highlighting affect?","Only cells whose exact values appear in the highlight list."],["Which paper sizes work?","A4, US Letter, A3, and US Legal are supported in portrait and landscape. A3 suits wall charts; Legal suits tall classroom displays."],["Can I make a 0–99 chart?","Yes. Choose the 0–99 chart to count from zero instead of one."],["Can I shade multiples for skip counting?","Yes. Use “Shade multiples of” to shade the multiples of 2, 3, 4, 5, or 10 in light grey, which stays readable when printed."],["Can I make a multiplication chart?","Yes. Choose the multiplication chart for a 1–10 times-table grid with the row and column headers highlighted."],["How do I highlight numbers?","Enter comma-separated numbers in the highlight box, for example 5, 10, 25 — only cells with those exact values are highlighted."],["How does the missing-numbers chart work?","Choose the missing-numbers chart, set the percentage of blank cells (10–90%), and shuffle for a different set of blanks. The complete chart is shown as a separate answer key below the worksheet, with its own download buttons."],["Can I add a heading and name and date lines?","Yes. Type a heading of up to 40 characters and turn on “Add name and date lines” to print Name and Date lines above the grid."]] },
  "blank-number-chart": { instructions:["The grid is an empty 1–100 chart — every cell is blank and ready to fill in by hand.","Type a custom heading of up to 40 characters, for example “Count to 100 — Class 2B”.","Turn on name and date lines when the sheet is for a class, then choose A4, US Letter, A3, or US Legal and export or print."], uses:["Count-to-100 writing practice","Fill-in-the-number assessments","Blank chart wall displays for early numeracy"], limitations:"The chart is a blank grid; it does not check answers. Print one copy per student and keep a completed chart for marking.", faqs:[["Is the blank chart really empty?","Yes. All 100 cells are blank. The completed 1–100 chart is on the main number charts page if you need it for marking."],["Can I add a heading?","Yes. Type a heading of up to 40 characters; it prints above the grid."],["Can I add name and date lines?","Yes. Turn on “Add name and date lines” to print Name and Date lines above the grid."],["Which paper sizes work?","A4, US Letter, A3, and US Legal, in portrait or landscape."]] },
  "missing-numbers-chart": { instructions:["Set the percentage of blank cells — 10% is a gentle warm-up, 30% is a typical class worksheet, and 50% or more is a real test.","Press “Shuffle missing numbers” for a different set of blanks at the same percentage.","Print or download the worksheet, then use the separate answer key below it for marking — the key has its own download buttons."], uses:["Missing-numbers practice for early numeracy","Quick classroom assessments","Homework sheets with a separate answer key"], limitations:"Blanks are chosen by a seeded random draw at the percentage you set, so the count of blank cells varies slightly from sheet to sheet. The answer key always shows the complete 1–100 chart.", faqs:[["How many numbers go missing?","The percentage you set — for example 30% blanks about 30 of the 100 numbers. The exact blanks change each time you shuffle."],["Where is the answer key?","Directly below the worksheet on this page, with its own PNG, PDF, and SVG download buttons, so you can hand out the worksheet and keep the solution."],["Can I make the worksheet harder?","Yes. Raise the percentage toward 90% for a harder sheet, or use the 1–120 chart for counting beyond 100."],["Can I add a heading and name lines?","Yes. Type a heading of up to 40 characters and turn on name and date lines, as on the main number charts page."]] },
  "number-chart-120": { instructions:["The grid counts from 1 to 120 in twelve rows of ten.","Enter comma-separated numbers to highlight, and shade multiples of 2, 3, 4, 5, or 10 for skip-counting practice.","Add a custom heading and name and date lines when the sheet is for a class, then choose A4, US Letter, A3, or US Legal and export or print."], uses:["Counting beyond 100 in early numeracy","Skip-counting practice to 120","Wall charts for classrooms that count past 100"], limitations:"The chart counts to 120 only. For counting to 100, use the main number charts page; for larger custom sequences, use the number grid generator.", faqs:[["Why a chart to 120?","Counting past 100 shows the pattern continuing — 110, 111, 112 — which is how children learn that the tens pattern repeats."],["Can I shade multiples?","Yes. “Shade multiples of” shades the multiples of 2, 3, 4, 5, or 10 in light grey."],["Which paper sizes work?","A4, US Letter, A3, and US Legal, in portrait and landscape. A3 suits a wall chart."],["Can I add a heading?","Yes. Type a heading of up to 40 characters; it prints above the grid."]] },
  "sudoku-generator": { instructions:["Choose a grid size — 4 × 4 for young children, 6 × 6 for the classroom, or the classic 9 × 9 — and a difficulty from easy to expert.","Enter a memorable seed, then choose how many puzzles go in the set (up to 6) and how many print on each page (1, 2, 4, or 6).","Download the puzzle pages, then download the answer pages separately — solutions are kept apart so you can hand out the worksheet and keep the answers.","Use “Copy puzzle link” to share one exact puzzle: the link opens the same puzzle for anyone who follows it.","Or solve on screen below the generator: click a cell, enter a digit, use notes for pencil marks, and undo when you change your mind."], uses:["Logic warm-ups","Classroom activity packs","Travel and screen-free puzzle sheets","4 × 4 and 6 × 6 puzzles for younger solvers"], limitations:"Difficulty is set by clue count (see the clue table below the tool), not by a human-solving-technique rating, so perceived challenge varies. The on-screen solver includes notes, undo, and a mistake count, but no hints and no timer.", faqs:[["Does every puzzle have one solution?","Yes. Every puzzle from this sudoku generator is accepted only while a solution counter confirms exactly one solution."],["What is a seed?","A seed is text used to reproduce the same generated puzzle with the same settings."],["Which grid sizes are available?","4 × 4, 6 × 6, and 9 × 9. The 4 × 4 grid uses the numbers 1–4 and suits young children; 6 × 6 uses 1–6; 9 × 9 uses 1–9."],["Which difficulties are available?","Easy, medium, hard, and expert, on all three grid sizes."],["How many clues does each puzzle have?","The exact counts are in the clue table below the tool, measured from the generator: 9 × 9 has 40 clues on easy, 33 on medium, 27 on hard, and 24–26 on expert; 6 × 6 has 26, 22, 18, and 16; 4 × 4 has 12, 10, 8, and 6."],["How many puzzles can I make at once?","Up to 6 puzzles per set, with 1, 2, 4, or 6 puzzles printed on each page."],["Can answers be printed separately?","Yes. Answer pages are a separate section with their own PNG, PDF, and SVG downloads — they are no longer printed after each puzzle."],["Can I share one puzzle with a class?","Yes. Pick the puzzle in the “Play on screen” section and press “Copy puzzle link”. The link carries a short puzzle ID; anyone who opens it gets the same puzzle with the same settings."],["Can I recreate the same puzzle later?","Yes. Reusing the same seed and settings reproduces the same puzzle, so you can share the seed with a class and everyone gets the identical puzzle."],["Can I solve a puzzle on screen?","Yes. Click a cell and enter a digit; switch Notes on for pencil marks, use Undo to step back, and Check to highlight wrong entries. A mistake counter counts wrong entries. There are no hints and no timer."]] },
  "blank-table-generator": { instructions:["Choose rows, columns, cell dimensions, and the number of shaded header rows.","Set border and header colors, paper size, and orientation.","Watch the page-fit message, then download or print."], uses:["Blank table generator pages for observation logs","Classroom data collection","Schedules, rubrics, and handwritten records"], limitations:"This tool makes an intentionally blank printable table; it does not calculate formulas or import spreadsheet data.", faqs:[["Can I remove the header?","Yes. Set Header rows to zero."],["Why is there a page-fit warning?","The chosen physical table is wider or taller than the printable preview area."],["Can I use landscape paper?","Yes. Both supported paper sizes can be rotated."],["What should I do if my table does not fit the page?","Reduce the rows, columns, or cell size until the page-fit message clears."]] },
  "virtual-graph-paper": { instructions:["Pick square, dot, or isometric paper and choose a drawing tool.","Draw with a mouse, pen, or touch; enable snapping for precise points.","Use undo and redo, then download PNG or editable SVG."], uses:["Coordinate sketches and geometry","Floor-plan drafts","Diagrams, arrows, and labeled technical notes"], limitations:"Autosave stays in this browser. Clearing site data removes the saved drawing, and the Pan control currently reserves the canvas from drawing rather than moving the viewport.", faqs:[["Does it work with touch?","Yes. Pointer events support touch, pen, and mouse input."],["Where is my drawing saved?","Objects are stored locally in this browser and are not uploaded."],["Is SVG editable?","Yes. The downloaded SVG contains vector shapes and text."]] },
  "pixel-art-generator": { instructions:["Choose grid dimensions — small grids for icons and sprites, large grids for detailed scenes — then pick a colour.","Draw with the pencil, erase mistakes, or flood-fill a connected area; switch on symmetry to mirror every stroke.","Use the eyedropper (Pick) to lift a colour straight from the canvas, or start from a heart, star, smiley, or sprite template.","Or turn a photo into pixel art: upload an image, choose a grid width and colour depth, and convert — then keep editing the result by hand.","Export the finished art as PNG at 5, 10, 20, or 30 pixels per cell, with a transparent background and grid lines if you want them, or download the SVG."], uses:["Pixel art generator sprites and icons for games","Color-by-number planning","Bead, knitting, and mosaic patterns","Turning a photo into blocky pixel art"], limitations:"The grid is limited to 64 × 64 to keep touch editing and local autosave responsive. Image conversion samples each grid cell and reduces colours to your chosen depth, so fine detail in a photo becomes blocks — that is the point of pixel art, but very small text in an image will not survive. Your drawing is autosaved in this browser only; clearing site data removes it.", faqs:[["What grid size should I use?","Match the grid to the job. Small grids of 8–16 cells per side suit icons, favicons, and simple sprites: every pixel matters and the picture reads at a glance. Medium grids of 20–32 cells suit characters, animals, and small scenes — this is the most useful range, and 24 × 24 is a good default. Large grids of 48–64 cells suit detailed scenes and image conversions, where you want shading and smooth edges. A bigger grid is not automatically better: it takes far longer to fill by hand, so start small, finish the picture, and only then try a larger version."],["What can I make with pixel art?","Game sprites and icons are the classic use: a character, a coin, a heart for a health bar, or a tileset for a small game. The same grid doubles as a pattern chart — bead patterns, cross-stitch, knitting, and mosaic layouts all read directly off the squares, one cell per bead, stitch, or tile. Teachers use it for colour-by-number planning and for simple symmetry exercises. And image conversion turns any photo into a poster-style pixel picture: portraits work well at 32–48 pixels wide with 16–32 colours, while logos and simple illustrations convert cleanly even at 16 pixels wide."],["How does image-to-pixel conversion work?","Upload a JPG, PNG, or WebP image (under 10 MB). Choose a grid width — 16, 24, 32, 48, or 64 pixels — and a colour depth of 8, 16, 32, or 64 colours. Conversion samples the average colour of each grid cell, then reduces the whole picture to your chosen number of colours, so the result is a genuine pixel grid you can keep editing with the pencil, fill, and eyedropper. The image never leaves your browser. Photos with strong shapes and few colours convert best; busy photos need a larger grid and more colours to stay recognisable."],["What do symmetry mode and the eyedropper do?","Symmetry mirrors every stroke as you draw: vertical mirrors left and right, horizontal mirrors top and bottom, and both mirrors in both directions at once. It is the fastest way to draw faces, hearts, vehicles, and anything else with a centre line — draw one side and the other appears. The eyedropper (Pick) lifts a colour from any cell on the canvas and makes it the active colour, then returns to the pencil, so you can match a shade you already used without hunting through the palette."],["How do the PNG export options work?","Choose a quality of 5, 10, 20, or 30 pixels per cell: 5 is a small file for thumbnails, 20 is a good default, and 30 gives a large crisp image for printing or posting. Turn on a transparent background and white cells stay transparent, so the art sits cleanly over any background — useful for game sprites and stickers. Turn on grid lines to include the cell outlines in the PNG, which suits pattern charts for beads or cross-stitch. SVG export is also available and stays sharp at any size."],["How does Fill work, and how many undo steps are there?","Fill replaces the connected region of the selected pixel with the active colour — connected means sharing an edge, not just touching at a corner. With symmetry on, fill also mirrors to the matching region. Undo goes back up to 40 steps, with redo, and the drawing autosaves in this browser as you work, so a refresh keeps your art."]] },
  "block-poster-maker": { instructions:["Upload a JPG, PNG, or WebP image under the stated memory limits.","Choose pages across and down, paper, orientation, margin, and overlap.","Review the page map, download the PDF, and print at 100% / Actual Size."], uses:["Block poster maker pages for classroom display lettering","Event signs","Large reference images assembled from home printers"], limitations:"Printers have different non-printable edges. Keep a safe margin and run a small test before printing many pages.", faqs:[["What does overlap do?","It repeats a narrow image strip on neighboring sheets to make alignment and taping easier."],["How do I assemble it?","Trim outer edges, align duplicated content, and tape pages from the back."],["Are images uploaded?","No. Loading, previewing, and tiling happen in the browser."],["Why should I print at 100%?","Printing at 100% / Actual Size keeps the overlap strips aligned so neighboring sheets match up when taped."]] },
  "multi-page-image-poster-generator": { instructions:["Upload an image and choose a page grid of up to 8 × 8.","Use Fit to preserve the whole image or Fill and crop/zoom to cover the poster.","Set overlap and margins, download the PDF, and print every page at Actual Size."], uses:["Photo enlargements","Educational maps and diagrams","Temporary murals and presentation backdrops"], limitations:"Files are capped at 20 MB and 40 megapixels to avoid unsafe browser-memory use. PDF raster quality depends on the source image.", faqs:[["What is the difference between Fit and Fill?","Fit preserves the full image; Fill covers the poster area and may crop edges."],["Can I make a 64-page poster?","Yes, though large exports use substantial memory and should start with a suitably sized source image."],["Why print at 100%?","Printer scaling changes the physical overlap and prevents neighboring image sections from aligning."]] },
  "calligraphy-generator": { instructions:["Type the text you want in a calligraphy style.","Open the style picker and choose Soft Cursive or Ink Flow — the two most calligraphic styles in the handwriting engine — and adjust size, ink color, and paper.","Review the rendered pages, then export the current page or the whole document as PNG, JPG, or PDF."], uses:["Calligraphy-style headings for cards, invitations, and posters","Practice pages for flowing letterforms","Decorative quotes and names in a handwritten look"], limitations:"This is a calligraphy-style text tool built on the site's handwriting engine: it renders typed text in flowing handwriting fonts. It is not a calligraphy pen simulator and does not reproduce pen angle, pressure, or stroke order.", faqs:[["Is this a real calligraphy pen simulator?","No. It renders your typed text in calligraphic handwriting styles (Soft Cursive and Ink Flow). You do not draw strokes with a pen."],["Which styles look most like calligraphy?","Soft Cursive and Ink Flow. Both use flowing, slanted letterforms; Ink Flow has the heavier, brush-like weight."],["Can I practise the letterforms on paper?","Yes. Use the handwriting worksheet generator in cursive mode to make tracing sheets from the same words, then print them."]] },
  "fancy-text-generator": { instructions:["Type or paste plain text in the input box.","Read the styled versions below — bold, italic, script, fraktur, double-struck, monospace, circled, and more.","Tap Copy next to a style to copy that version, then paste it wherever styled text is accepted."], uses:["Stylish display names and bios on social profiles","Decorative headings in messages, posts, and captions","Highlighting a word or name in plain-text places"], limitations:"Styles are made from Unicode characters, not from a font. Some apps, older devices, or screen readers may show them differently or read them letter by letter; plain text remains the most accessible choice.", faqs:[["Is this fancy text generator free?","Yes. Styling and copying happen in the browser with no account."],["Where can I paste fancy text?","Most apps that accept plain text accept these characters, including social bios, chats, and documents — but how they look depends on the app's font support."],["Why does a style look different in another app?","The characters are Unicode, so each app renders them with its own fonts. If a character is missing from that font, it may show as a box or a fallback glyph."]] },
  "handwriting-font": { instructions:["Type the text you want to preview.","Choose a handwriting font — Kalam is included with the site; the others load from Google Fonts — or upload your own .ttf or .otf font to preview it.","Adjust the size, review the live preview, and download it as a PNG, JPG, or PDF image. To get the Kalam font file itself, use the link to its official Google Fonts page."], uses:["Previewing how a name, quote, or heading looks in a handwriting font","Checking your own font file before using it in the handwriting studio","Exporting a handwriting-style text image for a card or worksheet"], limitations:"This page previews text in handwriting fonts and exports the preview as an image. It does not host font files for download: the only font download offered is a link to Kalam's official Google Fonts page (SIL Open Font License). Fonts you upload are loaded in this browser session only.", faqs:[["Can I download the fonts shown here?","Only Kalam, through a link to its official Google Fonts page, where it is published under the SIL Open Font License. The other preview fonts are not offered as downloads from this site."],["Can I preview my own handwriting font?","Yes. Upload a .ttf or .otf file (up to 5 MB). It is loaded in this browser only for the current session and also becomes available in the main handwriting studio."],["Is the preview a real font file I can install?","No. The export is an image (PNG, JPG, or PDF) of your text rendered in the font — useful for designs, not for installing the font on your computer."]] },
  "printable-worksheets": { instructions:["Pick a category: tracing and copy work, number practice, word puzzles, classroom sheets, or ready-made printable paper.","Open the worksheet maker for that category and enter your own words, numbers, or settings.","Generate the sheet, review the preview, then download or print it."], uses:["Tracing sheets for names, alphabets, and spelling words","Number charts and grids for early numeracy practice","Word search, scramble, and Sudoku sheets for classroom warm-ups"], limitations:"This page is a library and discovery hub: the worksheets themselves are made by the linked generators, each with its own settings and limits. It does not store your worksheets — generate a fresh sheet whenever you need one.", faqs:[["Are these worksheets free to print?","Yes. Every linked generator is free in the browser and requires no account."],["Can I make a worksheet with my own words?","Yes. The tracing, word search, scramble, and Sudoku makers all take your own words or numbers."],["What are the ready-made printables?","Ready-made paper from the site's own paper engine — for example primary handwriting practice paper, A4 5 mm graph paper, and an A4 Cornell notes template — as downloadable PDFs."]] },
  "handwriting-to-text": { instructions:["Choose the file type: PDF, Word (.docx), or plain text (.txt) — or paste text directly.","Upload the file. The extractor reads text already stored inside the file and shows it in the editable box.","Edit the text if needed, then copy it or download it as a .txt file."], uses:["Turning a typed PDF or Word document back into editable text","Recovering text from a file when you only have the document, not the original","Cleaning up pasted text before turning it into handwriting again"], limitations:"This page does NOT do handwriting OCR: it cannot read handwriting from a photo or a scanned image, and there is no OCR feature on this site. The extractors only read text already stored in a file — an image-only scanned PDF has no stored text, so it will come back empty. For handwritten notes, scan them with your phone and use your device's OCR (for example Google Lens or Apple Notes), then paste the recognised text here to clean it up.", faqs:[["Can this convert a photo of my handwriting into text?","No. This site has no handwriting OCR. Photograph or scan your notes and use your phone or computer's OCR app, then paste the recognised text here."],["Why did my scanned PDF come back empty?","A scanned PDF is a picture of pages, not stored text. The extractor can only read text that is already stored in the file."],["Which files can I upload?","PDF files up to 15 MB, .docx files up to 10 MB, and .txt files. Files never leave your browser."],["What happens to my file?","Extraction runs in your browser. Nothing is uploaded to a server."]] },
};
